export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // Portale cliente (08/10/2026): sul dominio dedicato risponde SOLO il portale (mai il webhook WhatsApp);
    // su workers.dev resta raggiungibile sotto /portale/ per collaudo.
    // Sito www.ilgiornalelavori.it (10/10/2026): chi ha il «lasciapassare» vede il sito completo (quello
    // dell'anteprima), tutti gli altri la pagina «in arrivo». Su workers.dev si prova sotto /sito-prova/.
    if (SITO_HOST.has(url.hostname)) {
      return sitoRoute(request, env, ctx, "");
    }
    if (url.pathname === "/sito-prova" || url.pathname.startsWith("/sito-prova/")) {
      return sitoRoute(request, env, ctx, "/sito-prova");
    }
    if (url.hostname === (env.PORTALE_HOST || PORTALE_HOST_PREDEFINITO)) {
      return portaleRoute(request, env, "");
    }
    if (url.pathname === "/portale" || url.pathname.startsWith("/portale/")) {
      if (url.pathname === "/portale") return Response.redirect(url.origin + "/portale/" + url.search, 301);
      return portaleRoute(request, env, "/portale");
    }

    if (request.method === "GET" && url.pathname === "/privacy") {
      return new Response(PRIVACY_HTML, {
        status: 200,
        headers: { "Content-Type": "text/html; charset=UTF-8" }
      });
    }

    if (request.method === "GET" && url.pathname === "/data-deletion") {
      return new Response(DATA_DELETION_HTML, {
        status: 200,
        headers: { "Content-Type": "text/html; charset=UTF-8" }
      });
    }

    if (request.method === "GET" && url.pathname === "/versione") {
      return new Response(RELAY_VERSIONE, {
        status: 200,
        headers: { "Content-Type": "text/plain; charset=UTF-8", "Cache-Control": "no-store" }
      });
    }

    // Stato della configurazione: dice SOLO se ogni variabile c'e' (sì/NO), mai il valore.
    if (request.method === "GET" && url.pathname === "/stato") {
      const si = (v) => (v ? "sì" : "NO");
      const righe = [
        RELAY_VERSIONE,
        "WHATSAPP_TOKEN: " + si(env.WHATSAPP_TOKEN),
        "SUPABASE_SERVICE_KEY: " + si(env.SUPABASE_SERVICE_KEY),
        "META_APP_SECRET: " + si(env.META_APP_SECRET),
        "META_VERIFY_TOKEN: " + si(env.META_VERIFY_TOKEN),
        "MAKE_WEBHOOK_URL: " + si(env.MAKE_WEBHOOK_URL),
        "MAKE_WEBHOOK_URL_MEDIA: " + si(env.MAKE_WEBHOOK_URL_MEDIA),
        "AI (trascrizione vocali): " + si(env.AI),
        "CHAT_UNICA: " + (env.CHAT_UNICA === "off" ? "spenta" : "accesa"),
        "TIMBRATURE (ENTRO/ESCO): " + (env.TIMBRATURE === "off" ? "spente dal Worker" : "accese (l'interruttore vero e' impostazioni.timbrature_attive)"),
        "RIMOZIONE (persone rimosse dai Tesserini): " + (env.RIMOZIONE === "off" ? "spenta dal Worker" : "accesa (elenco da persone_rimosse_numeri, in memoria 60 s)"),
        "MOVIMENTI (portale cliente): " + (env.MOVIMENTI === "off" ? "spenti dal Worker" : "accesi per tutti (su un telefono si spengono con ?movimenti=0)"),
        "CHIAMATE (risponditore in chat): " + (env.CHIAMATE === "off" ? "spento dal Worker" : "acceso (chiamata chiusa + messaggio di smistamento)"),
        "VOCE (assistente vocale OpenAI via SIP): " + (env.VOCE === "off" ? "spenta dal Worker" : "pronta") + " · OPENAI_API_KEY: " + si(env.OPENAI_API_KEY) + " · OPENAI_WEBHOOK_SECRET: " + si(env.OPENAI_WEBHOOK_SECRET) + " · modello " + (env.VOCE_MODELLO || "gpt-realtime-2.1-mini"),
        "Promemoria serale (cron): 15:30 e 16:30 UTC, invio solo dalle 17 di Roma"
      ];
      return new Response(righe.join("\n") + "\n", {
        status: 200,
        headers: { "Content-Type": "text/plain; charset=UTF-8", "Cache-Control": "no-store" }
      });
    }

    // Badge di cantiere (04/10/2026): le pagine dei tesserini vivono sulla Edge Function Supabase «badge»,
    // ma il gateway di Supabase le consegna come text/plain con CSP sandbox (dominio supabase.co):
    // il relay le ripropone sotto /badge/* con il content-type giusto. Qui non si tratta nessun dato.
    if (url.pathname === "/badge" || url.pathname.startsWith("/badge/")) {
      return badgeProxy(request, env);
    }
    // Cartello di cantiere (05/10/2026): pagina statica (public/cartello/index.html) + pagamento sulla
    // Edge Function Supabase «cartello». Anche qui non si tratta nessun dato: si passa e basta.
    if (url.pathname === "/cartello" || url.pathname.startsWith("/cartello/")) {
      return cartelloRoute(request, env);
    }
    if (request.method === "GET") {
      const mode = url.searchParams.get("hub.mode");
      const token = url.searchParams.get("hub.verify_token");
      const challenge = url.searchParams.get("hub.challenge");

      if (mode === "subscribe" && token === env.META_VERIFY_TOKEN) {
        return new Response(challenge, {
          status: 200,
          headers: { "Content-Type": "text/plain" },
        });
      }
      return new Response("Forbidden", { status: 403 });
    }

    // Amministrazione della chat unica (Flow, invii di prova, promemoria): chiave condivisa dal database.
    // VOCE (10/10/2026): webhook di OpenAI per le chiamate WhatsApp passate via SIP al modello vocale.
    if (request.method === "POST" && url.pathname === "/voce/openai") {
      try {
        return await voceWebhook(request, env, ctx);
      } catch (e) {
        return new Response("errore", { status: 500 });
      }
    }
    if (request.method === "POST" && url.pathname === "/admin") {
      try { return await chatUnicaAdmin(request, env); }
      catch (e) { return new Response(JSON.stringify({ errore: String((e && e.message) || e).slice(0, 300) }), { status: 500, headers: { "Content-Type": "application/json" } }); }
    }

    if (request.method === "POST") {
      const rawBody = await request.text();
      const signatureHeader = request.headers.get("X-Hub-Signature-256") || "";

      const valid = await verifySignature(rawBody, signatureHeader, env.META_APP_SECRET);
      if (!valid) {
        return new Response("Invalid signature", { status: 403 });
      }

      ctx.waitUntil(processAndForward(rawBody, env));

      return new Response("OK", { status: 200 });
    }

    return new Response("Method Not Allowed", { status: 405 });
  },

  // Cron di Cloudflare (wrangler.jsonc → triggers.crons): promemoria serale della chat unica
  // e, il venerdì, la domanda settimanale del cronoprogramma (CRONO_CRONS). Ogni cron fa solo il suo lavoro.
  async scheduled(event, env, ctx) {
    const cron = (event && event.cron) || "";
    if (BUONGIORNO_CRONS.indexOf(cron) !== -1) {
      ctx.waitUntil(chatUnicaBuongiorno(env, false, "").then((r) => {
        console.log(JSON.stringify({ buongiorno: r, cron }));
      }).catch((e) => {
        console.log(JSON.stringify({ buongiorno_errore: String((e && e.message) || e) }));
      }));
      return;
    }
    if (CRONO_CRONS.indexOf(cron) !== -1) {
      ctx.waitUntil(cronoSettimana(env, false).then((r) => {
        console.log(JSON.stringify({ crono_settimana: r, cron }));
      }).catch((e) => {
        console.log(JSON.stringify({ crono_settimana_errore: String((e && e.message) || e) }));
      }));
      return;
    }
    ctx.waitUntil(chatUnicaPromemoria(env, false).then((r) => {
      console.log(JSON.stringify({ promemoria: r, cron }));
    }).catch((e) => {
      console.log(JSON.stringify({ promemoria_errore: String((e && e.message) || e) }));
    }));
  },
};

async function verifySignature(rawBody, signatureHeader, appSecret) {
  if (!signatureHeader.startsWith("sha256=")) return false;
  const expectedHex = signatureHeader.slice(7);

  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(appSecret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const mac = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(rawBody));
  const macHex = [...new Uint8Array(mac)].map((b) => b.toString(16).padStart(2, "0")).join("");

  if (macHex.length !== expectedHex.length) return false;
  let diff = 0;
  for (let i = 0; i < macHex.length; i++) {
    diff |= macHex.charCodeAt(i) ^ expectedHex.charCodeAt(i);
  }
  return diff === 0;
}

async function forwardToMake(rawBody, makeWebhookUrl) {
  let payload;
  try {
    payload = JSON.parse(rawBody);
  } catch (e) {
    return;
  }

  const entries = payload.entry || [];
  for (const entry of entries) {
    const changes = entry.changes || [];
    for (const change of changes) {
      const value = change.value || {};
      if (!value.messages || value.messages.length === 0) continue;

      const bundle = {
        id: entry.id,
        time: value.messages[0] && value.messages[0].timestamp
          ? Number(value.messages[0].timestamp)
          : Math.floor(Date.now() / 1000),
        field: change.field,
        messages: value.messages,
        contacts: value.contacts || [],
      };

      try {
        await fetch(makeWebhookUrl, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(bundle),
        });
      } catch (e) {}
    }
  }
}

// ============================================================================
// PUNTO 46 — cattura media su Supabase Storage prima dell'inoltro a Make.
// FAIL-SAFE: senza WHATSAPP_TOKEN/SUPABASE_SERVICE_KEY, o se Meta/Supabase
// falliscono, il messaggio viene comunque inoltrato a Make come prima.
// La vecchia forwardToMake resta definita ma non è più chiamata.
// ============================================================================

async function processAndForward(rawBody, env) {
  let payload;
  try {
    payload = JSON.parse(rawBody);
  } catch (e) {
    return;
  }
  const makeWebhookUrl = env.MAKE_WEBHOOK_URL;
  const canCapture = !!(env.WHATSAPP_TOKEN && env.SUPABASE_SERVICE_KEY);
  const supabaseUrl = env.SUPABASE_URL || "https://rvigugiufrjmzedjstuz.supabase.co";
  const graph = "https://graph.facebook.com/" + (env.GRAPH_VERSION || "v21.0");
  const MEDIA_TYPES = ["image", "audio", "video", "document", "sticker"];

  // PUNTO 47 — instradamento dei media verso lo scenario "Foto e DDT" (fail-safe).
  // MAKE_WEBHOOK_URL_MEDIA assente  -> tutto al monolite, come prima.
  // MEDIA_SOLO_DA (numeri separati da virgola, facoltativo) -> accensione graduale:
  //   solo i media di quei mittenti vanno al nuovo scenario, gli altri restano al monolite.
  // Per tornare indietro basta rimuovere MAKE_WEBHOOK_URL_MEDIA: nessun deploy necessario.
  const mediaWebhookUrl = env.MAKE_WEBHOOK_URL_MEDIA || "";
  const ROUTE_MEDIA_TYPES = ["image", "document"];
  const soloDa = String(env.MEDIA_SOLO_DA || "").split(",").map((s) => s.replace(/[^0-9]/g, "")).filter(Boolean);

  // RIMOZIONE (09/10/2026): numeri delle persone rimosse dal Giornale Lavori (pagina Tesserini > «Cancella»),
  // letti dal database e tenuti in memoria 60 s. Un messaggio da un numero rimosso si ferma QUI: niente
  // cattura media, niente chat unica, niente Make. La persona riceve un avviso («accesso disattivato»,
  // nella sua lingua) al massimo una volta ogni 24 ore. Se il database non risponde vale l'ultima lista letta;
  // se non e' mai stata letta, la lista e' vuota e tutto prosegue come prima. Emergenza: variabile RIMOZIONE=off.
  let rimossi = [];
  if (env.RIMOZIONE !== "off") {
    try { rimossi = await rimossiNumeri(env, supabaseUrl); } catch (e) { rimossi = []; }
  }

  const entries = payload.entry || [];
  for (const entry of entries) {
    const changes = entry.changes || [];
    for (const change of changes) {
      const value = change.value || {};

      // CHIAMATE (10/10/2026): webhook «calls» della Calling API. Nessun operatore risponde:
      // la chiamata viene chiusa subito e chi chiama riceve in chat il messaggio di smistamento.
      // Gli eventi di chiamata non vanno MAI a Make. Emergenza: variabile CHIAMATE=off (le chiamate
      // restano senza risposta come prima, nessun messaggio inviato).
      if (change.field === "calls" || Array.isArray(value.calls)) {
        if (env.CHIAMATE !== "off" && Array.isArray(value.calls)) {
          try { await chiamateGestisci(value, env, supabaseUrl, graph, rimossi); } catch (e) {}
        }
        continue;
      }

      if (!value.messages || value.messages.length === 0) continue;

      if (rimossi.length) {
        const restano = [];
        for (const msg of value.messages) {
          if (rimossi.indexOf(String(msg.from || "")) === -1) { restano.push(msg); continue; }
          let bloccato = true;
          try { bloccato = await rimossoGestisci(msg, value, env, supabaseUrl, graph); } catch (e) { bloccato = true; }
          if (!bloccato) restano.push(msg); // ripristinata da meno di 60 s: il messaggio prosegue
        }
        if (restano.length === 0) continue;
        value.messages = restano;
      }

      // Cattura media (best-effort): non deve MAI impedire l'inoltro a Make.
      if (canCapture) {
        for (const msg of value.messages) {
          const tipo = msg.type;
          if (MEDIA_TYPES.indexOf(tipo) === -1) continue;
          const media = msg[tipo];
          if (!media || !media.id) continue;
          try {
            const captured = await captureMedia(media.id, tipo, msg, env, supabaseUrl, graph);
            if (captured && captured.signed_url) {
              // arricchisce il messaggio SENZA rimuovere nulla (monolite compatibile)
              media.link = captured.signed_url;
              media.storage_path = captured.storage_path;
              msg._media = captured;
            }
          } catch (e) {
            try {
              await logMedia(env, supabaseUrl, {
                message_id: msg.id, telefono: msg.from, tipo,
                mime: (media && media.mime_type) || null,
                storage_path: null, signed_url: null, signed_url_scade: null,
                dimensione_bytes: null, esito: "errore",
                errore: String((e && e.message) || e).slice(0, 500)
              });
            } catch (_) {}
          }
        }
      } else if (env.SUPABASE_SERVICE_KEY) {
        // 04/10/2026: senza WHATSAPP_TOKEN la cattura e' spenta. Lo si scrive nel registro
        // (esito 'errore'), cosi' il problema si vede subito invece di restare silenzioso.
        for (const msg of value.messages) {
          if (MEDIA_TYPES.indexOf(msg.type) === -1) continue;
          const media = msg[msg.type];
          try {
            await logMedia(env, supabaseUrl, {
              message_id: msg.id, telefono: msg.from, tipo: msg.type,
              mime: (media && media.mime_type) || null,
              storage_path: null, signed_url: null, signed_url_scade: null,
              dimensione_bytes: null, esito: "errore",
              errore: "WHATSAPP_TOKEN mancante sul relay: cattura non eseguita"
            });
          } catch (_) {}
        }
      }

      // CHAT UNICA: numeri ammessi (prova + produzione) letti dal database e tenuti in memoria 60 s.
      // Se il database non risponde la lista e' vuota: tutto va a Make come prima.
      let cu = { numeri: [], url: "", chiave: "" };
      try { cu = await chatUnicaConfig(env, supabaseUrl); } catch (e) {}

      // Inoltro a Make di un pacchetto (quello originale o uno costruito dalla chat unica):
      // foto e documenti allo scenario «Foto e DDT», tutto il resto al monolite. Stessa regola di sempre.
      const inoltraAMake = async (bundle) => {
        const m = bundle && Array.isArray(bundle.messages) ? bundle.messages[0] : null;
        if (!m) return false;
        const alMedia = !!mediaWebhookUrl
          && ROUTE_MEDIA_TYPES.indexOf(m.type) !== -1
          && (soloDa.length === 0 || soloDa.indexOf(String(m.from || "")) !== -1);
        const url = alMedia ? mediaWebhookUrl : makeWebhookUrl;
        if (!url) return false;
        try {
          await fetch(url, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(bundle)
          });
          return true;
        } catch (e) { return false; }
      };

      // Un invio per OGNI messaggio, in ordine: gli scenari leggono solo messages[1],
      // quindi se Meta raggruppa più messaggi in una notifica nessuno va perso.
      for (const msg of value.messages) {
        const bundle = {
          id: entry.id,
          time: msg.timestamp ? Number(msg.timestamp) : Math.floor(Date.now() / 1e3),
          field: change.field,
          metadata: value.metadata || {},
          messages: [msg],
          contacts: value.contacts || []
        };
        // TIMBRATURE (04/10/2026): «ENTRO» / «ESCO» come messaggio intero (anche «ENTRO #codice» dal QR
        // in baracca) e' una timbratura di presenza: la registra il database (timbratura_whatsapp), la
        // risposta parte da qui e il pacchetto NON va a Make. Vale per tutti i numeri registrati.
        // FAIL-SAFE: parola non riconosciuta, numero sconosciuto, interruttore spento, database o Meta
        // che non rispondono → il messaggio prosegue verso la chat unica / Make come se nulla fosse.
        // CRONOPROGRAMMA (09/10/2026): risposta ai pulsanti della domanda del venerdì (id «CRONO_<n>_<lettera>»).
        // La registra il database (crono_risposta), la conferma parte da qui, il pacchetto NON va a Make.
        // FAIL-SAFE: database o Meta che non rispondono → il messaggio prosegue come prima (Make lo ignora).
        // CHIAMATE (10/10/2026): risposta ai pulsanti del messaggio inviato dopo una chiamata (id «CHIAMATA_*»).
        if (env.CHIAMATE !== "off" && chiamataIdPulsante(msg)) {
          let presa = false;
          try { presa = await chiamataRispostaGestisci(msg, value, env, supabaseUrl, graph); } catch (e) { presa = false; }
          if (presa) continue;
        }
        if (env.CRONO !== "off" && cronoIdPulsante(msg)) {
          let presa = false;
          try { presa = await cronoRispostaGestisci(msg, value, env, supabaseUrl, graph); } catch (e) { presa = false; }
          if (presa) continue;
        }
        if (env.TIMBRATURE !== "off" && msg.type === "text" && timbraturaParola(msg.text && msg.text.body)) {
          let presa = false;
          try { presa = await timbraturaGestisci(msg, value, env, supabaseUrl, graph); } catch (e) { presa = false; }
          if (presa) continue;
        }
        if (cu.numeri.length && cu.numeri.indexOf(String(msg.from || "")) !== -1) {
          let presa = false;
          try { presa = await chatUnicaGestisci(msg, value, env, supabaseUrl, graph, cu, bundle, inoltraAMake); } catch (e) { presa = false; }
          if (presa) continue; // gestito dalla chat unica (prova o produzione): il pacchetto originale NON va a Make
        }
        await inoltraAMake(bundle);
      }
    }
  }
}

async function captureMedia(mediaId, tipo, msg, env, supabaseUrl, graph) {
  const token = env.WHATSAPP_TOKEN;
  const svc = env.SUPABASE_SERVICE_KEY;
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 25000);
  try {
    // 1) risolvi l'indirizzo del media presso Meta
    const metaResp = await fetch(graph + "/" + mediaId, {
      headers: { Authorization: "Bearer " + token }, signal: ctrl.signal
    });
    if (!metaResp.ok) throw new Error("resolve " + metaResp.status);
    const meta = await metaResp.json();
    const mime = meta.mime_type || (msg[tipo] && msg[tipo].mime_type) || "application/octet-stream";
    // 2) scarica i byte (il Bearer serve anche sull'URL del media)
    const binResp = await fetch(meta.url, {
      headers: { Authorization: "Bearer " + token }, signal: ctrl.signal
    });
    if (!binResp.ok) throw new Error("download " + binResp.status);
    const bytes = new Uint8Array(await binResp.arrayBuffer());
    // 3) percorso stabile nel bucket wa-media
    const now = new Date();
    const yyyy = now.getUTCFullYear();
    const mm = String(now.getUTCMonth() + 1).padStart(2, "0");
    const dd = String(now.getUTCDate()).padStart(2, "0");
    const path = tipo + "/" + yyyy + "/" + mm + "/" + dd + "/" + mediaId + extFromMime(mime);
    // 4) upload su Supabase Storage (upsert)
    const upResp = await fetch(supabaseUrl + "/storage/v1/object/wa-media/" + path, {
      method: "POST",
      headers: { Authorization: "Bearer " + svc, apikey: svc, "Content-Type": mime, "x-upsert": "true" },
      body: bytes, signal: ctrl.signal
    });
    if (!upResp.ok) throw new Error("upload " + upResp.status + " " + (await upResp.text()).slice(0, 120));
    // 5) URL firmato (7 giorni) per il consumo da Make senza header di auth
    const signResp = await fetch(supabaseUrl + "/storage/v1/object/sign/wa-media/" + path, {
      method: "POST",
      headers: { Authorization: "Bearer " + svc, apikey: svc, "Content-Type": "application/json" },
      body: JSON.stringify({ expiresIn: 604800 }), signal: ctrl.signal
    });
    if (!signResp.ok) throw new Error("sign " + signResp.status);
    const signJson = await signResp.json();
    const signedUrl = supabaseUrl + "/storage/v1" + signJson.signedURL;
    const scade = new Date(Date.now() + 604800 * 1000).toISOString();
    // 6) registro (idempotente sul WAMID)
    await logMedia(env, supabaseUrl, {
      message_id: msg.id, telefono: msg.from, tipo, mime, storage_path: path,
      signed_url: signedUrl, signed_url_scade: scade, dimensione_bytes: bytes.length,
      esito: "ok", errore: null
    });
    return { storage_path: path, signed_url: signedUrl, signed_url_scade: scade, mime, bytes: bytes.length, esito: "ok" };
  } finally {
    clearTimeout(timer);
  }
}

async function logMedia(env, supabaseUrl, r) {
  const svc = env.SUPABASE_SERVICE_KEY;
  await fetch(supabaseUrl + "/rest/v1/rpc/registra_media", {
    method: "POST",
    headers: { Authorization: "Bearer " + svc, apikey: svc, "Content-Type": "application/json" },
    body: JSON.stringify({
      p_message_id: r.message_id, p_telefono: r.telefono, p_tipo: r.tipo, p_mime: r.mime,
      p_storage_path: r.storage_path, p_signed_url: r.signed_url, p_signed_url_scade: r.signed_url_scade,
      p_dimensione_bytes: r.dimensione_bytes, p_esito: r.esito, p_errore: r.errore
    })
  });
}

function extFromMime(mime) {
  const m = (mime || "").split(";")[0].trim().toLowerCase();
  const map = {
    "image/jpeg": ".jpg", "image/png": ".png", "image/webp": ".webp", "image/gif": ".gif",
    "audio/ogg": ".ogg", "audio/mpeg": ".mp3", "audio/mp4": ".m4a", "audio/aac": ".aac", "audio/amr": ".amr",
    "video/mp4": ".mp4", "video/3gpp": ".3gp",
    "application/pdf": ".pdf",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet": ".xlsx",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document": ".docx",
    "application/vnd.ms-excel": ".xls", "application/msword": ".doc",
    "text/plain": ".txt", "application/zip": ".zip",
    "application/pkcs7-mime": ".p7m", "application/x-pkcs7-mime": ".p7m"
  };
  return map[m] || "";
}

// ============================================================================
// CHAT UNICA (04/10/2026). Due modalita', decise dal database (chat_unica_instrada):
//  • PROVA: numeri in impostazioni.chat_unica_numeri che hanno scritto «PROVA CHAT» — niente
//    finisce nel giornale vero, risponde solo la funzione.
//  • PRODUZIONE: numeri in impostazioni.chat_unica_produzione_numeri — la funzione classifica,
//    «prenota» sezione e cantiere nel database e dice a questo relay quali pacchetti mandare a
//    Make (originale, vocale trascritto, parti di un messaggio). Il giornale lo scrive Make.
// Le risposte partono da qui, sempre e solo verso chi ha scritto.
// FAIL-SAFE: se configurazione, instradamento o funzione non rispondono, il messaggio
// va a Make come oggi. Spegnimento senza deploy: impostazioni.chat_unica_attiva = 'no'
// (tutto), oppure svuotare chat_unica_produzione_numeri (solo la produzione).
// ============================================================================
const RELAY_VERSIONE = "wa-relay 2026-10-10 chat-unica-6 + badge-2 + cartello-2 (produzione, promemoria, flow, glossario vocali, tesserini, documenti, timbrature, cartello di cantiere PDF/X-1a) + portale-4 (portale cliente fuori da Make, installabile, visore foto a scorrimento, movimenti accesi per tutti: ?movimenti=0 li spegne su un telefono, MOVIMENTI=off per tutti) + crono-1 (domanda del venerdi sul cronoprogramma) + rimozione-1 (persone rimosse dai Tesserini: messaggi fermati prima di Make, avviso nella loro lingua) + chiamate-1 (chiamate WhatsApp chiuse in automatico, smistamento in chat) + voce-2 (assistente vocale OpenAI via SIP tramite centralino sip.ilgiornalelavori.it, webhook /voce/openai)";
let _chatUnicaCache = { t: 0, cfg: null };

async function chatUnicaRpc(env, supabaseUrl, nome, corpo, ms) {
  const svc = env.SUPABASE_SERVICE_KEY;
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), ms);
  try {
    const r = await fetch(supabaseUrl + "/rest/v1/rpc/" + nome, {
      method: "POST",
      headers: { Authorization: "Bearer " + svc, apikey: svc, "Content-Type": "application/json" },
      body: JSON.stringify(corpo), signal: ctrl.signal
    });
    if (!r.ok) throw new Error(nome + " " + r.status);
    const t = await r.text();
    return t ? JSON.parse(t) : null;
  } finally {
    clearTimeout(timer);
  }
}

async function chatUnicaConfig(env, supabaseUrl) {
  const vuota = { numeri: [], url: "", chiave: "", phone_number_id: "", promemoria_ora: "", glossario: "" };
  if (!env.SUPABASE_SERVICE_KEY || env.CHAT_UNICA === "off") return vuota;
  const ora = Date.now();
  if (_chatUnicaCache.cfg && ora - _chatUnicaCache.t < 60000) return _chatUnicaCache.cfg;
  let cfg = vuota;
  try {
    const r = await chatUnicaRpc(env, supabaseUrl, "chat_unica_config", {}, 3000);
    if (r && Array.isArray(r.numeri)) {
      cfg = { numeri: r.numeri.map((x) => String(x)), url: String(r.url || ""), chiave: String(r.chiave || ""),
        phone_number_id: String(r.phone_number_id || ""), promemoria_ora: String(r.promemoria_ora || ""),
        glossario: String(r.glossario_vocali || "").slice(0, 700) };
    }
  } catch (e) {}
  _chatUnicaCache = { t: ora, cfg };
  return cfg;
}

async function chatUnicaLog(env, supabaseUrl, telefono, messageId, tipo, dettaglio) {
  try {
    await chatUnicaRpc(env, supabaseUrl, "chat_unica_log",
      { p_telefono: telefono, p_message_id: messageId || null, p_tipo: tipo, p_dettaglio: String(dettaglio || "").slice(0, 1900) }, 3000);
  } catch (e) {}
}

async function chatUnicaInvia(graph, phoneId, token, payload) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 8000);
  try {
    const r = await fetch(graph + "/" + phoneId + "/messages", {
      method: "POST",
      headers: { Authorization: "Bearer " + token, "Content-Type": "application/json" },
      body: JSON.stringify(payload), signal: ctrl.signal
    });
    const t = await r.text();
    return { ok: r.ok, status: r.status, testo: t.slice(0, 300) };
  } finally {
    clearTimeout(timer);
  }
}

// Trascrizione dei vocali con Workers AI: attiva solo se nel Worker c'e' il collegamento «AI».
// Lingue plausibili in cantiere. Se Whisper ne rileva un'altra (il 04/10 un vocale italiano
// corto e' stato letto come islandese: «Þú operari, quattro óri»), si ritrascrive in italiano.
// Glossario (impostazioni.chat_unica_glossario_vocali + nomi dei cantieri, via chat_unica_config):
// passato a Whisper come initial_prompt per scrivere giusti i termini di cantiere («ponteggio», non
// «punteggio»). E' in italiano: per una lingua straniera plausibile si ritrascrive senza glossario.
const CHAT_UNICA_LINGUE = ["it", "ro", "sq", "uk", "ru", "pl", "es", "pt", "fr", "en", "de", "ar", "bn", "hi",
  "ur", "pa", "mk", "sr", "hr", "bs", "bg", "sk", "cs", "sl", "hu", "tr", "zh", "ta", "si", "ml", "tl", "fa", "el"];

async function chatUnicaTrascrivi(env, link, inizio, glossario) {
  const vuota = { testo: "", lingua: "?" };
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 10000);
  let buf;
  try {
    const r = await fetch(link, { signal: ctrl.signal });
    if (!r.ok) return vuota;
    buf = new Uint8Array(await r.arrayBuffer());
  } finally {
    clearTimeout(timer);
  }
  if (!buf || !buf.length || buf.length > 8 * 1024 * 1024) return vuota;
  let bin = "";
  for (let i = 0; i < buf.length; i += 0x8000) bin += String.fromCharCode.apply(null, buf.subarray(i, i + 0x8000));
  const audio = btoa(bin);
  const MODELLO = "@cf/openai/whisper-large-v3-turbo";
  const gl = String(glossario || "").trim().slice(0, 700);
  const base = gl ? { audio, initial_prompt: gl } : { audio };
  let out = await env.AI.run(MODELLO, base);
  const rilevata = String((out && out.transcription_info && out.transcription_info.language) || "?").toLowerCase();
  let lingua = rilevata;
  const tempo = () => Date.now() - (inizio || Date.now());
  // Nuovo tentativo solo se c'e' ancora tempo (il lavoro in background del Worker dura al massimo 30 s):
  // lingua implausibile → forzata in italiano; lingua straniera plausibile → di nuovo senza il glossario italiano.
  if (rilevata !== "?" && CHAT_UNICA_LINGUE.indexOf(rilevata) === -1 && tempo() < 15000) {
    try {
      const it = await env.AI.run(MODELLO, Object.assign({}, base, { language: "it" }));
      if (it && String(it.text || "").trim()) { out = it; lingua = "it (forzato, rilevato " + rilevata + ")"; }
    } catch (e) {}
  } else if (gl && rilevata !== "?" && rilevata !== "it" && tempo() < 15000) {
    try {
      const alt = await env.AI.run(MODELLO, { audio, language: rilevata });
      if (alt && String(alt.text || "").trim()) { out = alt; lingua = rilevata + " (senza glossario)"; }
    } catch (e) {}
  }
  return { testo: String((out && out.text) || "").trim().slice(0, 3900), lingua: lingua + (gl ? " · glossario" : "") };
}

// Testo con cui il database decide l'instradamento: il corpo per i testi, l'id del pulsante o della
// riga per gli interattivi (CU_… = chat unica), CU_FLOW per le risposte ai moduli (Flow).
function chatUnicaTestoInstrada(msg) {
  if (msg.type === "text" && msg.text) return String(msg.text.body || "");
  if (msg.type === "interactive" && msg.interactive) {
    const it = msg.interactive;
    if (it.nfm_reply || it.type === "nfm_reply") return "CU_FLOW";
    return String((it.button_reply && it.button_reply.id) || (it.list_reply && it.list_reply.id) || "");
  }
  return "";
}

// Ritorna true se il messaggio e' stato preso in carico dalla chat unica (quindi il pacchetto
// originale NON va a Make). In PRODUZIONE la funzione restituisce anche i pacchetti da rilanciare
// a Make (`inoltra`): li spedisce questo relay con la stessa regola di sempre (inoltraAMake).
// FAIL-SAFE di produzione: se la funzione non risponde o sbaglia, ritorna false e il messaggio
// originale va a Make come se la chat unica non esistesse.
async function chatUnicaGestisci(msg, value, env, supabaseUrl, graph, cfg, bundle, inoltraAMake) {
  const inizio = Date.now();
  const tel = String(msg.from || "");
  const phoneId = (value.metadata && value.metadata.phone_number_id) || "";
  const token = env.WHATSAPP_TOKEN;
  if (!phoneId || !cfg.url || !cfg.chiave) return false;
  if (!token) {
    // Senza token non si puo' rispondere: il messaggio va al Giornale normale, ma resta traccia.
    await chatUnicaLog(env, supabaseUrl, tel, msg.id, "funzione_errore",
      "WHATSAPP_TOKEN mancante sul relay: messaggio passato al Giornale normale");
    return false;
  }

  // 1) prova, produzione o Make? (in caso di dubbio: Make)
  let instr;
  try {
    instr = await chatUnicaRpc(env, supabaseUrl, "chat_unica_instrada",
      { p_telefono: tel, p_tipo: msg.type || "", p_testo: chatUnicaTestoInstrada(msg) }, 3000);
  } catch (e) {
    return false;
  }
  const destinazione = instr && instr.destinazione;
  if (destinazione !== "prova" && destinazione !== "produzione") return false;
  const produzione = destinazione === "produzione";

  // Da qui il messaggio e' della chat unica. In prova qualunque errore produce un avviso;
  // in produzione un errore della funzione passa il pacchetto originale a Make (fail-safe).
  try {
    await chatUnicaInvia(graph, phoneId, token, {
      messaging_product: "whatsapp", status: "read", message_id: msg.id, typing_indicator: { type: "text" }
    });
  } catch (e) {}

  let trascrizione = "";
  if (msg.type === "audio" && env.AI && msg.audio && msg.audio.link) {
    try {
      const tr = await chatUnicaTrascrivi(env, msg.audio.link, inizio, cfg.glossario);
      trascrizione = tr.testo;
      await chatUnicaLog(env, supabaseUrl, tel, msg.id, "trascrizione",
        (trascrizione ? "ok " + trascrizione.length + " caratteri" : "vuota") + " · lingua " + tr.lingua);
    } catch (e) {
      await chatUnicaLog(env, supabaseUrl, tel, msg.id, "trascrizione", "errore " + String((e && e.message) || e).slice(0, 300));
    }
  }

  let nome = "";
  try {
    const c = (value.contacts || []).find((x) => String(x.wa_id || "") === tel) || (value.contacts || [])[0];
    nome = (c && c.profile && c.profile.name) || "";
  } catch (e) {}

  // Tempo disponibile per la funzione: il lavoro in background del Worker dura al massimo 30 s
  const budget = Math.max(6000, Math.min(22000, 27000 - (Date.now() - inizio)));
  let invii = [];
  let inoltra = [];
  try {
    const ctrl = new AbortController();
    const timer = setTimeout(() => ctrl.abort(), budget);
    try {
      const r = await fetch(cfg.url, {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-chat-unica-chiave": cfg.chiave },
        body: JSON.stringify({ destinazione, evento: instr.evento || "messaggio", telefono: tel, nome, phone_number_id: phoneId,
          msg, trascrizione, bundle, budget_ms: budget }),
        signal: ctrl.signal
      });
      if (!r.ok) throw new Error("chat-unica HTTP " + r.status);
      const j = await r.json();
      invii = Array.isArray(j && j.invii) ? j.invii : [];
      inoltra = Array.isArray(j && j.inoltra) ? j.inoltra : [];
    } finally {
      clearTimeout(timer);
    }
  } catch (e) {
    await chatUnicaLog(env, supabaseUrl, tel, msg.id, "funzione_errore",
      String((e && e.message) || e) + (produzione ? " · messaggio passato a Make" : ""));
    if (produzione) return false; // Make riceve il pacchetto originale: nulla va perso
    invii = [{ messaging_product: "whatsapp", recipient_type: "individual", to: tel, type: "text",
      text: { body: "⚠️ Prova chat unica: non sono riuscito a elaborare il messaggio. Riprova tra poco (ESCI per tornare al Giornale normale)." } }];
  }

  for (const p of invii.slice(0, 6)) {
    if (!p || typeof p !== "object") continue;
    p.messaging_product = "whatsapp";
    p.to = tel; // le risposte vanno SOLO a chi ha scritto
    try {
      const esito = await chatUnicaInvia(graph, phoneId, token, p);
      if (!esito.ok) await chatUnicaLog(env, supabaseUrl, tel, msg.id, "invio_errore", esito.status + " " + esito.testo);
    } catch (e) {
      await chatUnicaLog(env, supabaseUrl, tel, msg.id, "invio_errore", String((e && e.message) || e));
    }
  }

  // Produzione: i pacchetti decisi dalla funzione (originale, vocale trascritto, parti) vanno a Make.
  let inoltrati = 0;
  for (const b of inoltra.slice(0, 4)) {
    if (!b || typeof b !== "object" || !Array.isArray(b.messages) || !b.messages.length) continue;
    // mittente sempre quello vero: nessun pacchetto puo' «parlare» a nome di un altro numero
    b.messages[0].from = tel;
    try { if (await inoltraAMake(b)) inoltrati++; } catch (e) {}
  }
  await chatUnicaLog(env, supabaseUrl, tel, msg.id, "presa",
    destinazione + " " + (instr.evento || "messaggio") + " " + (msg.type || "?") + " · risposte " + invii.length
    + " · a Make " + inoltrati + " · " + (Date.now() - inizio) + " ms");
  return true;
}

// ============================================================================
// PROMEMORIA SERALE (blocco 3, 04/10/2026): a chi ha scritto oggi, un riepilogo e il richiamo
// alle ore in economia, dentro la finestra gratuita delle 24 ore. Chi riceve e cosa riceve lo
// decide il database (chat_unica_promemoria_lista: impostazioni.chat_unica_promemoria_serale =
// no | produzione | tutti); qui si spedisce e si segna l'invio (una volta al giorno per numero).
// ============================================================================
function oraRoma() {
  try {
    const parti = new Intl.DateTimeFormat("en-GB", { timeZone: "Europe/Rome", hour: "2-digit", minute: "2-digit", hour12: false }).formatToParts(new Date());
    const h = Number((parti.find((p) => p.type === "hour") || {}).value);
    const m = Number((parti.find((p) => p.type === "minute") || {}).value);
    return { ora: isNaN(h) ? -1 : h, minuti: isNaN(m) ? 0 : m };
  } catch (e) { return { ora: -1, minuti: 0 }; }
}

async function chatUnicaPromemoria(env, forza) {
  const supabaseUrl = env.SUPABASE_URL || "https://rvigugiufrjmzedjstuz.supabase.co";
  const graph = "https://graph.facebook.com/" + (env.GRAPH_VERSION || "v21.0");
  const esito = { inviati: 0, errori: 0, saltato: "" };
  if (!env.SUPABASE_SERVICE_KEY || !env.WHATSAPP_TOKEN || env.CHAT_UNICA === "off") { esito.saltato = "configurazione"; return esito; }
  const cfg = await chatUnicaConfig(env, supabaseUrl);
  if (!cfg.phone_number_id) { esito.saltato = "phone_number_id"; return esito; }
  const attesa = Number(String(cfg.promemoria_ora || "17:30").split(":")[0]);
  const adesso = oraRoma();
  if (!forza && adesso.ora < (isNaN(attesa) ? 17 : attesa)) { esito.saltato = "ora " + adesso.ora + " < " + attesa; return esito; }
  let lista = [];
  try { lista = await chatUnicaRpc(env, supabaseUrl, "chat_unica_promemoria_lista", {}, 8000); } catch (e) { esito.saltato = "lista: " + String((e && e.message) || e); return esito; }
  for (const r of (Array.isArray(lista) ? lista : []).slice(0, 60)) {
    const tel = String(r.telefono || "").replace(/[^0-9]/g, "");
    if (!tel || !r.testo) continue;
    try {
      const inv = await chatUnicaInvia(graph, cfg.phone_number_id, env.WHATSAPP_TOKEN, {
        messaging_product: "whatsapp", recipient_type: "individual", to: tel, type: "text", text: { body: String(r.testo).slice(0, 4000), preview_url: false }
      });
      if (inv.ok) {
        esito.inviati++;
        await chatUnicaRpc(env, supabaseUrl, "chat_unica_promemoria_segna", { p_telefono: tel, p_testo: r.testo }, 5000);
        await chatUnicaLog(env, supabaseUrl, tel, null, "promemoria", "inviato · " + String(r.testo).slice(0, 200));
      } else {
        esito.errori++;
        await chatUnicaLog(env, supabaseUrl, tel, null, "promemoria_errore", inv.status + " " + inv.testo);
      }
    } catch (e) {
      esito.errori++;
      await chatUnicaLog(env, supabaseUrl, tel, null, "promemoria_errore", String((e && e.message) || e));
    }
  }
  return esito;
}

// ============================================================================
// BUONGIORNO (09/10/2026): ogni mattina, lun-ven non festivi, «📍 In che cantiere sei oggi?» a ogni operaio
// della chat unica, con i pulsanti dei suoi cantieri (id CU_CANT_<uuid>, gestiti dalla Edge Function chat-unica
// come una scelta del cantiere). Il database decide chi riceve (chat_unica_buongiorno_lista): solo se la
// finestra gratuita di 24 ore e' aperta, una volta al giorno, non a chi ha gia' scritto oggi. Costo: zero.
// Interruttori: impostazioni.chat_unica_buongiorno = si/no; variabile BUONGIORNO=off nel Worker.
// ============================================================================
const BUONGIORNO_CRONS = ["0 5,6 * * MON-FRI", "0 5 * * MON-FRI", "0 6 * * MON-FRI"]; // due passaggi UTC: il database spedisce dalle 7:00 di Roma, una volta al giorno

async function chatUnicaBuongiorno(env, forza, solo) {
  const supabaseUrl = env.SUPABASE_URL || "https://rvigugiufrjmzedjstuz.supabase.co";
  const graph = "https://graph.facebook.com/" + (env.GRAPH_VERSION || "v21.0");
  const esito = { versione: "buongiorno-2", inviati: 0, errori: 0, saltato: "" };
  if (!env.SUPABASE_SERVICE_KEY || !env.WHATSAPP_TOKEN || env.CHAT_UNICA === "off" || env.BUONGIORNO === "off") { esito.saltato = "configurazione"; return esito; }
  const cfg = await chatUnicaConfig(env, supabaseUrl);
  if (!cfg.phone_number_id) { esito.saltato = "phone_number_id"; return esito; }
  let lista = [];
  try { lista = await chatUnicaRpc(env, supabaseUrl, "chat_unica_buongiorno_lista", { p_forza: forza === true, p_solo: solo || null }, 10000); }
  catch (e) { esito.saltato = "lista: " + String((e && e.message) || e); return esito; }
  for (const r of (Array.isArray(lista) ? lista : []).slice(0, 200)) {
    const tel = String(r.telefono || "").replace(/[^0-9]/g, "");
    if (!tel || !r.payload || typeof r.payload !== "object") continue;
    if (cfg.numeri.indexOf(tel) === -1) continue; // solo numeri della chat unica
    const payload = r.payload;
    payload.messaging_product = "whatsapp";
    payload.to = tel;
    let ok = false, dettaglio = "";
    try {
      const inv = await chatUnicaInvia(graph, cfg.phone_number_id, env.WHATSAPP_TOKEN, payload);
      ok = inv.ok; dettaglio = inv.status + " " + inv.testo;
    } catch (e) { dettaglio = String((e && e.message) || e); }
    if (ok) esito.inviati++; else esito.errori++;
    try { await chatUnicaRpc(env, supabaseUrl, "chat_unica_buongiorno_segna", { p_telefono: tel, p_ok: ok, p_dettaglio: dettaglio.slice(0, 250) }, 5000); } catch (e) {}
    await chatUnicaLog(env, supabaseUrl, tel, null, ok ? "buongiorno" : "buongiorno_errore", dettaglio.slice(0, 300));
  }
  return esito;
}

// ============================================================================
// CRONOPROGRAMMA — domanda del venerdì (09/10/2026). Il database decide chi riceve e cosa
// (crono_settimana_lista: referenti in crono_referenti, lavorazioni in corso o in partenza, solo il
// venerdì dall'ora impostata, una volta a settimana per lavorazione); qui si spedisce e si segna.
// Fuori dalla finestra di 24 ore Meta rifiuta il messaggio libero: l'errore resta in crono_richieste.
// ============================================================================
const CRONO_CRONS = ["0 14,15 * * FRI", "0 14 * * FRI", "0 15 * * FRI"]; // Cloudflare: 1 = domenica, quindi si usa FRI (il 09/10 «5» era giovedi)

function cronoIdPulsante(msg) {
  if (!msg || msg.type !== "interactive" || !msg.interactive) return "";
  const it = msg.interactive;
  const id = String((it.button_reply && it.button_reply.id) || (it.list_reply && it.list_reply.id) || "");
  return /^CRONO_[0-9]+_[FCSIN]$/.test(id) ? id : "";
}

