async function cronoRispostaGestisci(msg, value, env, supabaseUrl, graph) {
  const id = cronoIdPulsante(msg);
  const tel = String(msg.from || "");
  const phoneId = (value.metadata && value.metadata.phone_number_id) || "";
  if (!id || !tel || !phoneId || !env.SUPABASE_SERVICE_KEY || !env.WHATSAPP_TOKEN) return false;
  const r = await chatUnicaRpc(env, supabaseUrl, "crono_risposta", { p_telefono: tel, p_id_pulsante: id }, 5000);
  if (!r || r.esito === "non_mio" || r.esito === "errore") return false;
  if (r.testo) {
    try {
      await chatUnicaInvia(graph, phoneId, env.WHATSAPP_TOKEN, {
        messaging_product: "whatsapp", recipient_type: "individual", to: tel, type: "text",
        context: { message_id: msg.id }, text: { body: String(r.testo).slice(0, 1000), preview_url: false }
      });
    } catch (e) {}
  }
  return true;
}

// ============================================================================
// AMMINISTRAZIONE (blocco 4): operazioni che richiedono il token WhatsApp, che vive SOLO qui.
// POST /admin con header x-chat-unica-chiave = impostazioni.chat_unica_chiave (letta dal database,
// mai nel codice). Azioni: waba (id dell'account WhatsApp Business), flow_lista, flow_crea,
// flow_dettaglio, flow_pubblica, flow_invia, invia (solo ai numeri della chat unica), promemoria.
// ============================================================================
async function graphJson(graph, token, percorso, metodo, corpo) {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 20000);
  try {
    const init = { method: metodo || "GET", headers: { Authorization: "Bearer " + token }, signal: ctrl.signal };
    if (corpo instanceof FormData) init.body = corpo;
    else if (corpo) { init.headers["Content-Type"] = "application/json"; init.body = JSON.stringify(corpo); }
    const r = await fetch(graph + "/" + percorso, init);
    const t = await r.text();
    let j = null;
    try { j = JSON.parse(t); } catch (e) { j = { testo: t.slice(0, 500) }; }
    return { ok: r.ok, status: r.status, dati: j };
  } finally {
    clearTimeout(timer);
  }
}

async function chatUnicaAdmin(request, env) {
  const supabaseUrl = env.SUPABASE_URL || "https://rvigugiufrjmzedjstuz.supabase.co";
  const graph = "https://graph.facebook.com/" + (env.GRAPH_VERSION || "v21.0");
  const rispondi = (o, status) => new Response(JSON.stringify(o), { status: status || 200, headers: { "Content-Type": "application/json; charset=UTF-8", "Cache-Control": "no-store" } });
  if (!env.WHATSAPP_TOKEN || !env.SUPABASE_SERVICE_KEY) return rispondi({ errore: "relay non configurato" }, 503);
  const cfg = await chatUnicaConfig(env, supabaseUrl);
  const chiave = request.headers.get("x-chat-unica-chiave") || "";
  if (!cfg.chiave || !chiave || chiave !== cfg.chiave) return rispondi({ errore: "non autorizzato" }, 403);
  let corpo;
  try { corpo = await request.json(); } catch (e) { return rispondi({ errore: "corpo non valido" }, 400); }
  const azione = String(corpo.azione || "");
  const token = env.WHATSAPP_TOKEN;
  const phoneId = String(corpo.phone_number_id || cfg.phone_number_id || "");

  if (azione === "waba") {
    const r = await graphJson(graph, token, "debug_token?input_token=" + encodeURIComponent(token));
    const d = (r.dati && r.dati.data) || {};
    // solo gli id e i permessi: mai il token
    return rispondi({ ok: r.ok, status: r.status, app_id: d.app_id, type: d.type, scopes: d.scopes, granular_scopes: d.granular_scopes, expires_at: d.expires_at, errore: r.dati && r.dati.error });
  }
  // VOCE (10/10/2026): lettura e scrittura delle impostazioni chiamate/SIP del numero (Graph /settings).
  if (azione === "impostazioni_leggi") {
    const r = await graphJson(graph, token, phoneId + "/settings" + (corpo.credenziali === true ? "?include_sip_credentials=true" : ""));
    if (r.dati && r.dati.calling && r.dati.calling.sip && Array.isArray(r.dati.calling.sip.servers)) {
      for (const s of r.dati.calling.sip.servers) if (s && s.sip_user_password) s.sip_user_password = "(presente, nascosta)";
    }
    return rispondi(r);
  }
  if (azione === "impostazioni_scrivi") {
    if (!corpo.calling || typeof corpo.calling !== "object") return rispondi({ errore: "calling mancante" }, 400);
    const r = await graphJson(graph, token, phoneId + "/settings", "POST", { calling: corpo.calling });
    await chatUnicaLog(env, supabaseUrl, "0", null, "admin_impostazioni", JSON.stringify(corpo.calling).slice(0, 900) + " → " + r.status);
    return rispondi(r);
  }
  if (azione === "numero") {
    const r = await graphJson(graph, token, phoneId + "?fields=id,display_phone_number,verified_name,quality_rating,name_status");
    return rispondi(r);
  }
  if (azione === "flow_lista") {
    if (!corpo.waba_id) return rispondi({ errore: "waba_id mancante" }, 400);
    const r = await graphJson(graph, token, String(corpo.waba_id) + "/flows?fields=id,name,status,categories,validation_errors,json_version");
    return rispondi(r);
  }
  if (azione === "flow_crea") {
    if (!corpo.waba_id || !corpo.nome || !corpo.flow_json) return rispondi({ errore: "waba_id, nome e flow_json obbligatori" }, 400);
    const dati = { name: String(corpo.nome), categories: Array.isArray(corpo.categorie) && corpo.categorie.length ? corpo.categorie : ["OTHER"],
      flow_json: typeof corpo.flow_json === "string" ? corpo.flow_json : JSON.stringify(corpo.flow_json), publish: corpo.pubblica === true };
    const r = await graphJson(graph, token, String(corpo.waba_id) + "/flows", "POST", dati);
    return rispondi(r);
  }
  if (azione === "flow_aggiorna_json") {
    if (!corpo.flow_id || !corpo.flow_json) return rispondi({ errore: "flow_id e flow_json obbligatori" }, 400);
    const fd = new FormData();
    fd.append("name", "flow.json");
    fd.append("asset_type", "FLOW_JSON");
    fd.append("file", new Blob([typeof corpo.flow_json === "string" ? corpo.flow_json : JSON.stringify(corpo.flow_json)], { type: "application/json" }), "flow.json");
    const r = await graphJson(graph, token, String(corpo.flow_id) + "/assets", "POST", fd);
    return rispondi(r);
  }
  if (azione === "flow_dettaglio") {
    if (!corpo.flow_id) return rispondi({ errore: "flow_id mancante" }, 400);
    const r = await graphJson(graph, token, String(corpo.flow_id) + "?fields=id,name,status,categories,validation_errors,json_version,data_api_version,preview");
    return rispondi(r);
  }
  if (azione === "flow_pubblica") {
    if (!corpo.flow_id) return rispondi({ errore: "flow_id mancante" }, 400);
    const r = await graphJson(graph, token, String(corpo.flow_id) + "/publish", "POST", {});
    return rispondi(r);
  }
  if (azione === "flow_elimina") {
    if (!corpo.flow_id) return rispondi({ errore: "flow_id mancante" }, 400);
    const r = await graphJson(graph, token, String(corpo.flow_id), "DELETE");
    return rispondi(r);
  }
  if (azione === "flow_invia" || azione === "invia") {
    const a = String(corpo.a || "").replace(/[^0-9]/g, "");
    if (!a || cfg.numeri.indexOf(a) === -1) return rispondi({ errore: "destinatario non ammesso: solo i numeri della chat unica" }, 400);
    if (!phoneId) return rispondi({ errore: "phone_number_id mancante" }, 400);
    let payload;
    if (azione === "invia") {
      payload = corpo.payload && typeof corpo.payload === "object" ? corpo.payload : null;
      if (!payload) return rispondi({ errore: "payload mancante" }, 400);
    } else {
      if (!corpo.flow_id) return rispondi({ errore: "flow_id mancante" }, 400);
      const parametri = {
        flow_message_version: "3",
        flow_token: String(corpo.flow_token || ("ECO:" + a + ":" + Date.now())),
        flow_id: String(corpo.flow_id),
        flow_cta: String(corpo.cta || "Compila le ore").slice(0, 30),
        flow_action: "navigate",
        flow_action_payload: { screen: String(corpo.schermata || "ORE"), data: corpo.dati && typeof corpo.dati === "object" ? corpo.dati : {} }
      };
      if (corpo.bozza !== false) parametri.mode = "draft";
      payload = { messaging_product: "whatsapp", recipient_type: "individual", to: a, type: "interactive",
        interactive: { type: "flow",
          header: corpo.intestazione ? { type: "text", text: String(corpo.intestazione).slice(0, 60) } : undefined,
          body: { text: String(corpo.corpo || "Ore in economia di oggi: compila il modulo, ci vogliono 20 secondi.").slice(0, 1024) },
          footer: corpo.pie ? { text: String(corpo.pie).slice(0, 60) } : undefined,
          action: { name: "flow", parameters: parametri } } };
      if (!payload.interactive.header) delete payload.interactive.header;
      if (!payload.interactive.footer) delete payload.interactive.footer;
    }
    payload.messaging_product = "whatsapp";
    payload.to = a;
    const r = await chatUnicaInvia(graph, phoneId, token, payload);
    await chatUnicaLog(env, supabaseUrl, a, null, "admin_invio", azione + " " + r.status + " " + r.testo.slice(0, 200));
    return rispondi(r);
  }
  if (azione === "promemoria") {
    const r = await chatUnicaPromemoria(env, corpo.forza === true);
    return rispondi(r);
  }
  if (azione === "buongiorno") {
    const solo = String(corpo.solo || "").replace(/[^0-9]/g, "");
    if (corpo.forza === true && !solo) return rispondi({ errore: "con forza serve il destinatario (solo)" }, 400);
    const r = await chatUnicaBuongiorno(env, corpo.forza === true, solo);
    return rispondi(r);
  }
  if (azione === "crono_settimana") {
    const r = await cronoSettimana(env, corpo.forza === true);
    return rispondi(r);
  }
  return rispondi({ errore: "azione sconosciuta" }, 400);
}

// ---------------------------------------------------------------------------
// Badge di cantiere — ripropone le pagine della Edge Function Supabase «badge»
// (tesserini di riconoscimento, pagina ufficio, pagina pubblica di verifica del QR).
// Il gateway di Supabase riscrive il content-type delle pagine HTML in text/plain e aggiunge
// una CSP «sandbox» sul dominio supabase.co: qui si rimette il content-type HTML.
// Metodi ammessi: GET, HEAD, POST (modulo foto/date, al massimo 8 MB). Le risposte 303 passano
// al browser così come sono: i collegamenti li compone già la funzione con impostazioni.badge_url.
const BADGE_FUNZIONE_URL = "https://rvigugiufrjmzedjstuz.supabase.co/functions/v1/badge";

async function badgeProxy(request, env) {
  const metodo = request.method;
  if (metodo !== "GET" && metodo !== "HEAD" && metodo !== "POST") {
    return new Response("Method Not Allowed", { status: 405, headers: { Allow: "GET, HEAD, POST" } });
  }
  const inUrl = new URL(request.url);
  const base = env.BADGE_FUNZIONE_URL || BADGE_FUNZIONE_URL;
  const target = base + inUrl.pathname.replace(/^\/badge/, "") + inUrl.search;

  const init = { method: metodo, headers: {}, redirect: "manual" };
  // Il cookie del codice di controllo (DL/CSE sulla pagina del QR) viaggia in entrambe le direzioni;
  // il relay non lo legge e non lo conserva.
  const cookie = request.headers.get("cookie");
  if (cookie) init.headers["cookie"] = cookie;
  if (metodo === "POST") {
    const ct = request.headers.get("content-type") || "";
    init.headers["content-type"] = ct;
    const corpo = await request.arrayBuffer();
    if (corpo.byteLength > 11 * 1024 * 1024) {
      return new Response("Modulo troppo grande (fotografie fino a 8 MB, attestati fino a 10 MB).", {
        status: 413, headers: { "Content-Type": "text/plain; charset=UTF-8" }
      });
    }
    init.body = corpo;
  }

  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 25000);
  init.signal = ctrl.signal;
  let r;
  try {
    r = await fetch(target, init);
  } catch (e) {
    clearTimeout(timer);
    return new Response("Il servizio dei tesserini non risponde in questo momento. Riprova tra qualche minuto.", {
      status: 502, headers: { "Content-Type": "text/plain; charset=UTF-8", "Cache-Control": "no-store" }
    });
  }
  clearTimeout(timer);

  const headers = new Headers();
  headers.set("Content-Type", "text/html; charset=UTF-8");
  headers.set("Cache-Control", "no-store");
  for (const h of ["x-robots-tag", "referrer-policy", "x-frame-options", "x-content-type-options"]) {
    const v = r.headers.get(h);
    if (v) headers.set(h, v);
  }
  const loc = r.headers.get("location");
  if (loc) headers.set("Location", loc);
  // Solo il cookie della funzione (cdc): quelli dell'infrastruttura Supabase (__cf_bm, Domain=supabase.co)
  // non riguardano questo dominio e il browser li scarterebbe comunque.
  const cookies = typeof r.headers.getSetCookie === "function" ? r.headers.getSetCookie() : [];
  for (const sc of cookies) if (/^cdc=/.test(sc)) headers.append("Set-Cookie", sc);
  if (metodo === "HEAD" || r.status === 303 || r.status === 302 || r.status === 304) {
    return new Response(null, { status: r.status, headers });
  }
  return new Response(r.body, { status: r.status, headers });
}

// ---------------------------------------------------------------------------
// Cartello di cantiere (05/10/2026) — il generatore del cartello (modulo, anteprima e PDF nel browser).
// GET /cartello (o /cartello/) serve il file statico public/cartello/index.html tramite il binding ASSETS;
// /cartello/checkout, /cartello/verifica e /cartello/scarico vanno alla Edge Function Supabase «cartello»
// (Checkout Stripe da 9,00 € + IVA e registro delle vendite). Il relay non legge e non conserva nulla.
const CARTELLO_FUNZIONE_URL = "https://rvigugiufrjmzedjstuz.supabase.co/functions/v1/cartello";
const CARTELLO_API = new Set(["/checkout", "/verifica", "/scarico", "/stato"]);

async function cartelloRoute(request, env) {
  const metodo = request.method;
  const inUrl = new URL(request.url);
  const sotto = (inUrl.pathname.replace(/^\/cartello/, "") || "/").replace(/\/+$/, "") || "/";

  if (sotto === "/" || sotto === "/index.html") {
    if (metodo !== "GET" && metodo !== "HEAD") {
      return new Response("Method Not Allowed", { status: 405, headers: { Allow: "GET, HEAD" } });
    }
    if (!env.ASSETS) {
      return new Response("La pagina del cartello non e' disponibile su questa versione del relay.", {
        status: 503, headers: { "Content-Type": "text/plain; charset=UTF-8", "Cache-Control": "no-store" }
      });
    }
    const r = await env.ASSETS.fetch(new Request(new URL("/cartello/index.html", inUrl.origin), { method: "GET", headers: request.headers }));
    const headers = new Headers(r.headers);
    headers.set("Content-Type", "text/html; charset=UTF-8");
    headers.set("Cache-Control", "public, max-age=300");
    headers.set("X-Content-Type-Options", "nosniff");
    headers.set("X-Frame-Options", "DENY");
    headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
    if (metodo === "HEAD") return new Response(null, { status: r.status, headers });
    return new Response(r.body, { status: r.status, headers });
  }

  if (!CARTELLO_API.has(sotto)) {
    return new Response("Pagina non trovata", { status: 404, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
  }
  if (metodo !== "GET" && metodo !== "POST") {
    return new Response("Method Not Allowed", { status: 405, headers: { Allow: "GET, POST" } });
  }
  const base = env.CARTELLO_FUNZIONE_URL || CARTELLO_FUNZIONE_URL;
  const init = { method: metodo, headers: {} };
  const ip = request.headers.get("cf-connecting-ip");
  if (ip) init.headers["x-forwarded-for"] = ip;
  const ua = request.headers.get("user-agent");
  if (ua) init.headers["user-agent"] = ua;
  if (metodo === "POST") {
    init.headers["content-type"] = request.headers.get("content-type") || "application/json";
    const corpo = await request.arrayBuffer();
    if (corpo.byteLength > 64 * 1024) {
      return new Response(JSON.stringify({ errore: "richiesta troppo grande" }), { status: 413, headers: { "Content-Type": "application/json" } });
    }
    init.body = corpo;
  }
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 25000);
  init.signal = ctrl.signal;
  let r;
  try {
    r = await fetch(base + sotto + inUrl.search, init);
  } catch (e) {
    clearTimeout(timer);
    return new Response(JSON.stringify({ errore: "servizio non raggiungibile in questo momento" }), {
      status: 502, headers: { "Content-Type": "application/json", "Cache-Control": "no-store" }
    });
  }
  clearTimeout(timer);
  return new Response(r.body, {
    status: r.status,
    headers: { "Content-Type": r.headers.get("content-type") || "application/json", "Cache-Control": "no-store" }
  });
}

// ============================================================================
// TIMBRATURE (04/10/2026). «ENTRO» / «ESCO» (o le varianti qui sotto) scritti come messaggio intero,
// facoltativamente seguiti da «#codice» (le prime 8 cifre dell'id del cantiere, stampate nel QR della
// baracca). Il riconoscimento definitivo lo fa il database (timbratura_parola/timbratura_whatsapp):
// qui si filtra solo per non interrogarlo a ogni messaggio. Nessuna posizione viene letta ne' chiesta.
// Spegnimento senza deploy: impostazioni.timbrature_attive = 'no'; emergenza: variabile TIMBRATURE=off.
// ============================================================================
const TIMBRATURE_PAROLE = [
  "ENTRO", "ENTRATA", "ENTRATO", "ENTRATI", "SONO ENTRATO", "SONO ENTRATA", "INIZIO TURNO", "INIZIO LAVORO",
  "TIMBRO ENTRATA", "TIMBRA ENTRATA", "ENTRO IN CANTIERE", "CLOCK IN", "INTRU", "AM INTRAT", "HYRA", "HYJ",
  "ENTRADA", "WEJSCIE", "WCHODZE",
  "ESCO", "USCITA", "USCITO", "USCITI", "SONO USCITO", "SONO USCITA", "FINE TURNO", "FINE LAVORO",
  "TIMBRO USCITA", "TIMBRA USCITA", "ESCO DAL CANTIERE", "CLOCK OUT", "IES", "AM IESIT", "DOLA",
  "SALIDA", "SAIDA", "WYJSCIE", "WYCHODZE"
];

// Ritorna la parola riconosciuta (maiuscola, senza accenti) oppure "" se il testo non e' una timbratura.
function timbraturaParola(testo) {
  let v = String(testo || "");
  if (!v || v.length > 60) return "";
  v = v.normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/ł/g, "l").toUpperCase();
  v = v.replace(/[^A-Z0-9#]+/g, " ").trim();
  if (!v || v.length > 40) return "";
  const m = v.match(/^(.+?)(?: ?#[0-9A-F]{4,8})?$/);
  if (!m) return "";
  const parola = m[1].trim();
  return TIMBRATURE_PAROLE.indexOf(parola) !== -1 ? parola : "";
}

// Ritorna true se il messaggio e' stato registrato (o riconosciuto come doppione) e la risposta e'
// partita: il pacchetto NON va a Make. Ritorna false in ogni altro caso (il messaggio prosegue).
async function timbraturaGestisci(msg, value, env, supabaseUrl, graph) {
  const tel = String(msg.from || "");
  const phoneId = (value.metadata && value.metadata.phone_number_id) || "";
  const token = env.WHATSAPP_TOKEN;
  if (!env.SUPABASE_SERVICE_KEY || !token || !phoneId) return false;
  let nome = "";
  try {
    const c = (value.contacts || []).find((x) => String(x.wa_id || "") === tel) || (value.contacts || [])[0];
    nome = (c && c.profile && c.profile.name) || "";
  } catch (e) {}
  const quando = msg.timestamp ? new Date(Number(msg.timestamp) * 1000).toISOString() : null;
  let r;
  try {
    r = await chatUnicaRpc(env, supabaseUrl, "timbratura_whatsapp", {
      p_telefono: tel, p_testo: String(msg.text && msg.text.body || ""), p_message_id: msg.id || null,
      p_timestamp: quando, p_nome: nome
    }, 6000);
  } catch (e) {
    return false; // database muto: il messaggio va avanti come sempre
  }
  if (!r || typeof r !== "object") return false;
  if (r.esito === "duplicato") return true; // Meta ha ripetuto la notifica: gia' registrata, niente doppia risposta
  if (r.esito === "ignora" || !r.risposta) return false;
  try {
    await chatUnicaInvia(graph, phoneId, token, {
      messaging_product: "whatsapp", status: "read", message_id: msg.id
    });
  } catch (e) {}
  try {
    const inv = await chatUnicaInvia(graph, phoneId, token, {
      messaging_product: "whatsapp", recipient_type: "individual", to: tel, type: "text",
      text: { body: String(r.risposta).slice(0, 4000), preview_url: false }
    });
    if (!inv.ok) await chatUnicaLog(env, supabaseUrl, tel, msg.id, "timbratura_invio_errore", inv.status + " " + inv.testo);
  } catch (e) {
    await chatUnicaLog(env, supabaseUrl, tel, msg.id, "timbratura_invio_errore", String((e && e.message) || e));
  }
  await chatUnicaLog(env, supabaseUrl, tel, msg.id, "timbratura",
    (r.tipo || "?") + " " + (r.esito || "") + (r.cantiere ? " · " + r.cantiere : "") + (r.origine ? " · " + r.origine : "") + (r.ora ? " · " + r.ora : ""));
  return true;
}

// ============================================================================
// RIMOZIONE (09/10/2026) — persone tolte dal Giornale Lavori dalla pagina Tesserini («Cancella»,
// persone.rimosso_il). Il database e' la sola fonte: qui si tiene in memoria per 60 s l'elenco dei
// numeri rimossi (persone_rimosse_numeri) e, per ogni messaggio da uno di quei numeri, si chiede al
// database se mandare l'avviso (persona_rimossa_avviso: al massimo uno ogni 24 ore, testo nella lingua
// della persona). «Ripristina» dalla stessa pagina riapre tutto entro 60 s. Nessuno scenario Make coinvolto.
// ============================================================================
let _rimossiCache = { t: 0, numeri: [] };

async function rimossiNumeri(env, supabaseUrl) {
  if (!env.SUPABASE_SERVICE_KEY) return [];
  const ora = Date.now();
  if (ora - _rimossiCache.t < 60000) return _rimossiCache.numeri;
  try {
    const r = await chatUnicaRpc(env, supabaseUrl, "persone_rimosse_numeri", {}, 3000);
    const numeri = Array.isArray(r) ? r.map((x) => String(x).replace(/[^0-9]/g, "")).filter(Boolean) : [];
    _rimossiCache = { t: ora, numeri };
    return numeri;
  } catch (e) {
    // database muto: vale l'ultima lista letta (anche se vecchia), ma si riprova al prossimo messaggio
    _rimossiCache.t = ora - 50000;
    return _rimossiCache.numeri;
  }
}

// Ritorna true se il messaggio va fermato (persona rimossa: avviso mandato se dovuto), false se la persona
// risulta nel frattempo ripristinata (il messaggio prosegue). In caso di dubbio (database muto) ferma.
async function rimossoGestisci(msg, value, env, supabaseUrl, graph) {
  const tel = String(msg.from || "");
  let r;
  try {
    r = await chatUnicaRpc(env, supabaseUrl, "persona_rimossa_avviso", { p_telefono: tel }, 6000);
  } catch (e) {
    return true;
  }
  if (!r || typeof r !== "object") return true;
  if (r.rimossa !== true) {
    _rimossiCache = { t: 0, numeri: [] }; // la lista in memoria e' vecchia: si rilegge al prossimo messaggio
    return false;
  }
  const phoneId = (value.metadata && value.metadata.phone_number_id) || "";
  const token = env.WHATSAPP_TOKEN;
  if (token && phoneId && msg.id) {
    try {
      await chatUnicaInvia(graph, phoneId, token, { messaging_product: "whatsapp", status: "read", message_id: msg.id });
    } catch (e) {}
  }
  let dettaglio = (r.nome || "?") + " · " + (msg.type || "?") + " · fermato";
  if (r.avvisa === true && r.testo && token && phoneId) {
    try {
      const inv = await chatUnicaInvia(graph, phoneId, token, {
        messaging_product: "whatsapp", recipient_type: "individual", to: tel, type: "text",
        text: { body: String(r.testo).slice(0, 4000), preview_url: false }
      });
      dettaglio += inv.ok ? " · avviso inviato (" + (r.lingua || "it") + ")" : " · avviso NON inviato " + inv.status + " " + inv.testo;
    } catch (e) {
      dettaglio += " · avviso NON inviato " + String((e && e.message) || e);
    }
  }
  await chatUnicaLog(env, supabaseUrl, tel, msg.id, "rimosso", dettaglio);
  return true;
}

