function portaleMovimenti(request, inUrl, base, env) {
  const param = inUrl.searchParams.get("movimenti");
  const cookie = /(?:^|;\s*)gl_mov=([01])(?:;|$)/.exec(request.headers.get("Cookie") || "");
  const scelta = param === "1" || param === "0" ? param : (cookie ? cookie[1] : "");
  // Accesi per tutti dal 10/10/2026: si spengono solo con la scelta esplicita di quel telefono (?movimenti=0 -> cookie gl_mov=0)
  // o con l'interruttore d'emergenza del Worker (MOVIMENTI=off), che vale per tutti e dal telefono non si scavalca.
  const attivi = !(env && env.MOVIMENTI === "off") && scelta !== "0";
  let setCookie = null;
  if (param === "1" || param === "0") setCookie = "gl_mov=" + param + "; Path=" + base + "/; Max-Age=7776000; SameSite=Lax; Secure";
  return { attivi, setCookie };
}

async function portaleRoute(request, env, prefisso) {
  const metodo = request.method;
  if (metodo !== "GET" && metodo !== "HEAD") {
    return new Response("Method Not Allowed", { status: 405, headers: { Allow: "GET, HEAD" } });
  }
  const inUrl = new URL(request.url);
  const base = prefisso; // "" sul dominio dedicato, "/portale" su workers.dev
  let sotto = inUrl.pathname.slice(prefisso.length) || "/";

  if (sotto === "/manifest.webmanifest") {
    const manifest = {
      id: base + "/",
      name: "Il Giornale Lavori",
      short_name: "Giornale Lavori",
      description: "I cantieri della tua impresa: giornale, rapportini, DDT, foto e documenti.",
      lang: "it",
      start_url: base + "/",
      scope: base + "/",
      display: "standalone",
      orientation: "portrait",
      background_color: "#FFFFFF",
      theme_color: PORTALE_COLORE,
      icons: [
        { src: base + "/icona-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
        { src: base + "/icona-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
        { src: base + "/icona-maskable-192.png", sizes: "192x192", type: "image/png", purpose: "maskable" },
        { src: base + "/icona-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" }
      ]
    };
    return new Response(JSON.stringify(manifest), {
      status: 200,
      headers: { "Content-Type": "application/manifest+json; charset=UTF-8", "Cache-Control": "public, max-age=3600" }
    });
  }

  if (sotto === "/sw.js") {
    return new Response(PORTALE_SW, {
      status: 200,
      headers: { "Content-Type": "application/javascript; charset=UTF-8", "Cache-Control": "no-cache" }
    });
  }

  if (PORTALE_ICONE.has(sotto)) {
    const r = await env.ASSETS.fetch(new Request(inUrl.origin + "/portale" + sotto));
    if (!r.ok) return new Response("Not Found", { status: 404 });
    const h = new Headers(r.headers);
    h.set("Cache-Control", "public, max-age=86400");
    return new Response(metodo === "HEAD" ? null : r.body, { status: 200, headers: h });
  }

  if (sotto === "/robots.txt") {
    return new Response("User-agent: *\nDisallow: /\n", { status: 200, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
  }

  if (sotto !== "/" && sotto !== "/index.html") {
    return new Response("Not Found", { status: 404, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
  }

  const tGrezzo = inUrl.searchParams.get("t");
  if (tGrezzo === null) {
    return new Response(metodo === "HEAD" ? null : portaleIngresso(base, ""), { status: 200, headers: portaleHtmlHeaders() });
  }
  const m = String(tGrezzo).match(/[0-9a-fA-F]{64}/);
  if (!m) {
    return new Response(portaleIngresso(base, "Il collegamento non è completo. Incollalo di nuovo per intero."), { status: 200, headers: portaleHtmlHeaders() });
  }
  const token = m[0].toLowerCase();
  const commessa = (inUrl.searchParams.get("c") || "").slice(0, 64);

  if (!env.SUPABASE_SERVICE_KEY) {
    return new Response("Servizio non configurato.", { status: 503, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
  }
  const supabaseUrl = env.SUPABASE_URL || "https://rvigugiufrjmzedjstuz.supabase.co";
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), 25000);
  let html;
  try {
    const r = await fetch(supabaseUrl + "/rest/v1/rpc/dashboard_html", {
      method: "POST",
      headers: {
        "apikey": env.SUPABASE_SERVICE_KEY,
        "Authorization": "Bearer " + env.SUPABASE_SERVICE_KEY,
        "Content-Type": "application/json",
        "Accept": "application/json"
      },
      body: JSON.stringify({ p_token: token, p_commessa: commessa }),
      signal: ctrl.signal
    });
    if (!r.ok) throw new Error("rpc " + r.status);
    html = await r.json();
    if (typeof html !== "string") throw new Error("risposta non testuale");
  } catch (e) {
    clearTimeout(timer);
    return new Response(portaleIngresso(base, "Il servizio non risponde in questo momento. Riprova tra qualche minuto."), {
      status: 503, headers: portaleHtmlHeaders({ "Retry-After": "60" })
    });
  }
  clearTimeout(timer);

  // Pagina valida = contiene i collegamenti con il gettone (le pagine di errore non lo riportano mai).
  const valida = html.indexOf("?t=" + token) !== -1;
  const mov = portaleMovimenti(request, inUrl, base, env);
  let script = valida
    ? "<script>(function(){try{localStorage.setItem('gl_portale_t','" + token + "')}catch(e){}" + portaleScriptSw(base) + "})();</script>"
    : "<script>(function(){try{if(localStorage.getItem('gl_portale_t')==='" + token + "')localStorage.removeItem('gl_portale_t')}catch(e){}})();</script>";
  const testa = portaleTesta(base) + (valida && mov.attivi ? PORTALE_MOVIMENTI_STILE : "");
  html = html.indexOf("</head>") !== -1 ? html.replace("</head>", testa + "</head>") : html;
  if (valida && mov.attivi) script = PORTALE_MOVIMENTI_SCRIPT + script;   // dopo visore e frecce (che vengono anteposti qui sotto)
  if (valida && html.indexOf("<img") !== -1) script = PORTALE_VISORE + script;
  if (valida && html.indexOf('<nav class="schede"') !== -1) script = PORTALE_FRECCE + script;
  html = html.lastIndexOf("</body>") !== -1
    ? html.slice(0, html.lastIndexOf("</body>")) + script + html.slice(html.lastIndexOf("</body>"))
    : html + script;
  return new Response(metodo === "HEAD" ? null : html, {
    status: 200, headers: portaleHtmlHeaders(mov.setCookie ? { "Set-Cookie": mov.setCookie } : null)
  });
}


// ---------------------------------------------------------------------------
// Sito www.ilgiornalelavori.it (10/10/2026, scelta di Filippo: «Pagina "in arrivo"»).
// Finché il sito non è pubblico: i visitatori vedono public/sito/in-arrivo.html; chi apre una volta
// https://www.ilgiornalelavori.it/?lasciapassare=<chiave> riceve un cookie (1 anno) e da lì vede il sito completo,
// servito dall'anteprima (Worker ilgiornalelavori-anteprima) senza cambiare il modo in cui il sito si carica.
// /cartello resta sempre pubblico (è un servizio in vendita). La chiave non è nel codice: qui c'è solo la sua impronta.
// Per aprire il sito a tutti: SITO_PUBBLICO = true (oppure variabile SITO_PUBBLICO="si" nel pannello).
const SITO_HOST = new Set(["www.ilgiornalelavori.it", "ilgiornalelavori.it"]);
const SITO_ORIGINE_PREDEFINITA = "https://ilgiornalelavori-anteprima.filippo-obetti.workers.dev";
const SITO_IMPRONTA_CHIAVE = "f7c98691564e3d89ed20e09c9d342b7d1700cfeb1df787286a4cd2f60d017ae8";
const SITO_PUBBLICO = false;
const SITO_COOKIE = "gl_lasciapassare";

async function sitoSha256(t) {
  const b = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(t));
  return Array.from(new Uint8Array(b)).map((x) => x.toString(16).padStart(2, "0")).join("");
}

function sitoLeggiCookie(request, nome) {
  const c = request.headers.get("cookie") || "";
  for (const parte of c.split(";")) {
    const i = parte.indexOf("=");
    if (i > 0 && parte.slice(0, i).trim() === nome) return decodeURIComponent(parte.slice(i + 1).trim());
  }
  return "";
}

async function sitoInArrivo(request, env, base) {
  const r = await env.ASSETS.fetch(new Request(new URL(request.url).origin + "/sito/in-arrivo.html"));
  const h = new Headers({ "Content-Type": "text/html; charset=UTF-8", "Cache-Control": "no-store", "X-Robots-Tag": "noindex" });
  return new Response(request.method === "HEAD" ? null : await r.text(), { status: 200, headers: h });
}

async function sitoRoute(request, env, ctx, prefisso) {
  const url = new URL(request.url);
  // dominio nudo → www
  if (url.hostname === "ilgiornalelavori.it") {
    return Response.redirect("https://www.ilgiornalelavori.it" + url.pathname + url.search, 301);
  }
  const sotto = url.pathname.slice(prefisso.length) || "/";

  // il generatore del cartello è sempre pubblico, anche a sito chiuso
  if (sotto === "/cartello" || sotto.startsWith("/cartello/")) {
    const u = new URL(request.url); u.pathname = sotto;
    return cartelloRoute(new Request(u.toString(), request), env);
  }

  const pubblico = SITO_PUBBLICO || env.SITO_PUBBLICO === "si";
  let ammesso = pubblico;

  // apertura del lasciapassare: ?lasciapassare=<chiave> → cookie e ritorno alla stessa pagina senza la chiave
  const proposta = url.searchParams.get("lasciapassare");
  if (proposta !== null) {
    if (proposta && (await sitoSha256(proposta)) === SITO_IMPRONTA_CHIAVE) {
      url.searchParams.delete("lasciapassare");
      const h = new Headers({ Location: url.pathname + (url.search || ""), "Cache-Control": "no-store" });
      h.append("Set-Cookie", SITO_COOKIE + "=" + encodeURIComponent(proposta) + "; Path=/; Max-Age=31536000; Secure; HttpOnly; SameSite=Lax");
      return new Response(null, { status: 302, headers: h });
    }
    if (proposta === "") {   // ?lasciapassare= vuoto: si esce
      const h = new Headers({ Location: prefisso + "/", "Cache-Control": "no-store" });
      h.append("Set-Cookie", SITO_COOKIE + "=; Path=/; Max-Age=0; Secure; HttpOnly; SameSite=Lax");
      return new Response(null, { status: 302, headers: h });
    }
  }
  if (!ammesso) {
    const c = sitoLeggiCookie(request, SITO_COOKIE);
    ammesso = !!c && (await sitoSha256(c)) === SITO_IMPRONTA_CHIAVE;
  }

  if (!ammesso) {
    if (sotto === "/robots.txt") return new Response("User-agent: *\nDisallow: /\n", { status: 200, headers: { "Content-Type": "text/plain; charset=UTF-8" } });
    if (sotto !== "/" && sotto !== "/index.html") return Response.redirect(url.origin + prefisso + "/", 302);
    return sitoInArrivo(request, env);
  }

  // sito completo: lo serve l'anteprima, così il sito si continua a caricare come oggi
  const origine = (env.SITO_ORIGINE || SITO_ORIGINE_PREDEFINITA).replace(/\/+$/, "");
  const init = { method: request.method, headers: new Headers(request.headers), redirect: "manual" };
  init.headers.delete("cookie");
  init.headers.delete("host");
  if (request.method !== "GET" && request.method !== "HEAD") init.body = await request.arrayBuffer();
  let r;
  try { r = await fetch(origine + sotto + url.search, init); }
  catch (e) { return new Response("Il sito non risponde in questo momento.", { status: 502, headers: { "Content-Type": "text/plain; charset=UTF-8" } }); }
  const h = new Headers(r.headers);
  h.set("X-Robots-Tag", "noindex, nofollow");
  if (!pubblico) h.set("Cache-Control", "private, no-store");
  const loc = h.get("location");
  if (loc && loc.startsWith(origine)) h.set("Location", loc.slice(origine.length) || "/");
  return new Response(request.method === "HEAD" ? null : r.body, { status: r.status, headers: h });
}

// ============================================================================
// CHIAMATE (10/10/2026) — risponditore in chat, nessun operatore umano.
// Una chiamata WhatsApp in arrivo (webhook «calls», evento «connect») viene RIFIUTATA subito via
// Calling API e chi chiama riceve in chat un messaggio con tre pulsanti di smistamento.
// La chiamata apre la finestra di 24 ore di assistenza: il messaggio e' gratuito e a testo libero.
// Le risposte ai pulsanti (id «CHIAMATA_*») sono gestite qui e non vanno a Make.
// Protezioni: stessa chiamata gestita una sola volta; al massimo un messaggio di smistamento ogni
// 10 minuti per numero; i numeri rimossi dai Tesserini vengono solo rifiutati, senza messaggio.
// FAIL-SAFE: se Meta non risponde la chiamata finisce comunque come «Nessuna risposta» dopo 30-60 s.
// ============================================================================
const _chiamateViste = new Map();   // call_id -> ms
const _chiamateMenu = new Map();    // telefono -> ms ultimo messaggio di smistamento
const CHIAMATE_MENU_PAUSA_MS = 10 * 60 * 1000;

const CHIAMATA_TESTO_MENU =
  "📞 Ciao! Il Giornale Lavori non risponde al telefono: qui in chat è tutto automatico, a qualsiasi ora.\n\n" +
  "Tocca il pulsante che fa per te 👇";

const CHIAMATA_RISPOSTE = {
  CHIAMATA_CANTIERE:
    "👷 Perfetto. Scrivi qui come fai sempre: testi, foto, documenti di trasporto e anche messaggi vocali " +
    "vengono registrati nel giornale del tuo cantiere.\n\n" +
    "Dopo ogni messaggio ricevi la conferma ✅: se non arriva, rimandalo tra qualche minuto.",
  CHIAMATA_INFO:
    "🏗️ Il Giornale Lavori trasforma i messaggi WhatsApp del cantiere (testi, foto, vocali, DDT) nel " +
    "giornale dei lavori, giorno per giorno, senza nessuna app da installare per chi lavora in cantiere.\n\n" +
    "Le persone che scrivono sono illimitate e l'attivazione è automatica.\n\n" +
    "Il sito www.ilgiornalelavori.it è in arrivo: da lì potrai richiedere il listino.",
  CHIAMATA_PROBLEMA:
    "🔧 Prova così:\n" +
    "1) rimanda qui il messaggio, la foto o il vocale;\n" +
    "2) attendi qualche minuto la conferma ✅;\n" +
    "3) se la conferma non arriva ancora, avvisa l'ufficio della tua impresa: sistemerà l'accesso dal pannello del Giornale Lavori."
};

function chiamataIdPulsante(msg) {
  if (!msg || msg.type !== "interactive" || !msg.interactive) return "";
  const it = msg.interactive;
  const id = String((it.button_reply && it.button_reply.id) || (it.list_reply && it.list_reply.id) || "");
  return Object.prototype.hasOwnProperty.call(CHIAMATA_RISPOSTE, id) ? id : "";
}

function chiamateMenuPayload(tel) {
  return {
    messaging_product: "whatsapp",
    recipient_type: "individual",
    to: tel,
    type: "interactive",
    interactive: {
      type: "button",
      body: { text: CHIAMATA_TESTO_MENU },
      action: {
        buttons: [
          { type: "reply", reply: { id: "CHIAMATA_CANTIERE", title: "Lavoro in cantiere" } },
          { type: "reply", reply: { id: "CHIAMATA_INFO", title: "Info sul servizio" } },
          { type: "reply", reply: { id: "CHIAMATA_PROBLEMA", title: "Ho un problema" } }
        ]
      }
    }
  };
}

async function chiamateGestisci(value, env, supabaseUrl, graph, rimossi) {
  const phoneId = (value.metadata && value.metadata.phone_number_id) || "";
  const token = env.WHATSAPP_TOKEN;
  const ora = Date.now();
  for (const [k, t] of _chiamateViste) if (ora - t > 3600 * 1000) _chiamateViste.delete(k);

  for (const c of value.calls) {
    if (!c || typeof c !== "object") continue;
    const evento = String(c.event || "");
    const callId = String(c.id || "");
    let tel = String(c.from || "").replace(/[^0-9]/g, "");
    if (!tel) {
      try {
        const ct = (value.contacts || [])[0];
        tel = String((ct && ct.wa_id) || "").replace(/[^0-9]/g, "");
      } catch (e) {}
    }

    // Diagnosi (10/10/2026, prova SIP): ogni evento di chiamata finisce nel registro, con eventuali errori di Meta.
    if (env.SUPABASE_SERVICE_KEY) {
      const extra = { event: c.event, status: c.status, direction: c.direction, duration: c.duration, errors: value.errors || c.errors };
      await chatUnicaLog(env, supabaseUrl, tel || "?", null, "chiamata_evento", callId + " · " + JSON.stringify(extra).slice(0, 1500));
    }
    if (evento !== "connect" || String(c.direction || "USER_INITIATED") !== "USER_INITIATED") continue;
    if (!c.session) continue; // senza SDP = modalita' SIP: la chiamata la gestisce il server SIP, non va rifiutata qui
    if (!callId || _chiamateViste.has(callId)) continue;
    _chiamateViste.set(callId, ora);
    if (!phoneId || !token) continue;

    // 1) chiudere subito la chiamata
    let rifiuto = "";
    try {
      const r = await graphJson(graph, token, phoneId + "/calls", "POST",
        { messaging_product: "whatsapp", call_id: callId, action: "reject" });
      rifiuto = r.ok ? "rifiutata" : "rifiuto non riuscito " + r.status + " " + JSON.stringify(r.dati).slice(0, 200);
    } catch (e) {
      rifiuto = "rifiuto non riuscito " + String((e && e.message) || e).slice(0, 200);
    }

    // 2) messaggio di smistamento (non ai numeri rimossi, non piu' di uno ogni 10 minuti)
    let esitoMenu = "";
    if (!tel) {
      esitoMenu = "numero non disponibile (nome utente WhatsApp): nessun messaggio";
    } else if (rimossi && rimossi.indexOf(tel) !== -1) {
      esitoMenu = "numero rimosso: nessun messaggio";
    } else if (_chiamateMenu.has(tel) && ora - _chiamateMenu.get(tel) < CHIAMATE_MENU_PAUSA_MS) {
      esitoMenu = "messaggio gia' inviato negli ultimi 10 minuti";
    } else {
      try {
        const inv = await chatUnicaInvia(graph, phoneId, token, chiamateMenuPayload(tel));
        if (inv.ok) { _chiamateMenu.set(tel, ora); esitoMenu = "smistamento inviato"; }
        else esitoMenu = "smistamento NON inviato " + inv.status + " " + inv.testo;
      } catch (e) {
        esitoMenu = "smistamento NON inviato " + String((e && e.message) || e).slice(0, 200);
      }
    }
    if (env.SUPABASE_SERVICE_KEY) {
      await chatUnicaLog(env, supabaseUrl, tel || "?", null, "chiamata", callId + " · " + rifiuto + " · " + esitoMenu);
    }
  }
}

async function chiamataRispostaGestisci(msg, value, env, supabaseUrl, graph) {
  const id = chiamataIdPulsante(msg);
  const tel = String(msg.from || "");
  const phoneId = (value.metadata && value.metadata.phone_number_id) || "";
  const token = env.WHATSAPP_TOKEN;
  if (!id || !tel || !phoneId || !token) return false;
  try {
    await chatUnicaInvia(graph, phoneId, token, { messaging_product: "whatsapp", status: "read", message_id: msg.id });
  } catch (e) {}
  let dettaglio = id;
  try {
    const inv = await chatUnicaInvia(graph, phoneId, token, {
      messaging_product: "whatsapp",
      recipient_type: "individual",
      to: tel,
      type: "text",
      text: { body: CHIAMATA_RISPOSTE[id], preview_url: false }
    });
    dettaglio += inv.ok ? " · risposta inviata" : " · risposta NON inviata " + inv.status + " " + inv.testo;
  } catch (e) {
    dettaglio += " · risposta NON inviata " + String((e && e.message) || e).slice(0, 200);
  }
  if (env.SUPABASE_SERVICE_KEY) await chatUnicaLog(env, supabaseUrl, tel, msg.id, "chiamata_scelta", dettaglio);
  return true;
}

